-- Lane A figures for ap_statistics: generated by build_load_sql.py, do not hand-edit.
-- 3 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('density_curve', 'Probability density curves', 'Normal and chi-square densities with the area under them shaded: the normal curve, the standard normal, the empirical rule''s nested bands, probability as an area, a critical value bounding the middle C%, the tail a p-value lives in, and the chi-square family''s skew. Chi-square is drawn for EVEN degrees of freedom only, so its gamma is an exact factorial and the two renderers agree byte for byte. What a shaded band claims is checked against the integral, not trusted to the fill.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-skew-right', 'ap_statistics', 'density_curve', 'Skewed right: the longer tail is on the right', 'Skewed right', 'The tail toward larger values is longer (figure 1 of 3)', 'A density curve whose right tail is longer than its left tail.', 'A density curve with its peak near the left and a long tail stretching to the right toward larger values, while the left side drops steeply to zero. The right tail is clearly longer than the left tail, so the distribution is skewed right. The skew is named for the longer tail, not for the side where the peak is. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'Skew is named for the longer tail, not for the side where most of the data are.', true, null, '["Longer right tail", "Skewed right"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "chi_square", "df": 4, "style": "solid"}], "texts": [{"x": 11.5, "y": 0.065, "label": "longer right tail"}], "skew_checks": [{"curve": 0, "direction": "right"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-skew-left', 'ap_statistics', 'density_curve', 'Skewed left: the longer tail is on the left', 'Skewed left', 'The tail toward smaller values is longer (figure 2 of 3)', 'A density curve whose left tail is longer than its right tail.', 'A density curve with its peak near the right and a long tail stretching to the left toward smaller values, while the right side drops steeply to zero. The left tail is clearly longer than the right tail, so the distribution is skewed left. The skew is named for the longer tail, not for the side where the peak is. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'Skew is named for the longer tail, not for the side where most of the data are.', true, null, '["Longer left tail", "Skewed left"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "chi_square", "df": 4, "mirror_about": 16, "style": "solid"}], "texts": [{"x": 4.5, "y": 0.065, "label": "longer left tail"}], "skew_checks": [{"curve": 0, "direction": "left"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-skew-symmetric', 'ap_statistics', 'density_curve', 'Approximately symmetric: the halves mirror each other', 'Approximately symmetric', 'The left half mirrors the right half (figure 3 of 3)', 'A bell-shaped density curve whose two halves are mirror images.', 'A bell-shaped density curve with its peak in the middle and a dashed vertical line through the centre. The left half is the mirror image of the right half, so the two tails are the same length and the distribution is approximately symmetric. Illustrative data.', 'value of the variable', 'relative likelihood (density)', 'Symmetric means the left half mirrors the right half, so neither tail is longer.', true, null, '["Left half mirrors the right half", "Approximately symmetric"]'::jsonb, '{"x_range": [0.0, 16.0], "x_ticks": [[0.0, "0"], [4.0, "4"], [8.0, "8"], [12.0, "12"], [16.0, "16"]], "curves": [{"kind": "normal", "mu": 8.0, "sigma": 2.7, "style": "solid"}], "vlines": [{"x": 8.0, "label": "mirror line", "caption": null}], "skew_checks": [{"curve": 0, "direction": "none"}]}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next3-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-skew-right', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Skew direction is named by the longer tail' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-skew-left', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Skew direction is named by the longer tail' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-skew-symmetric', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Skew direction is named by the longer tail' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-skew-right', 'stats-skew-left', 'stats-skew-symmetric') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-skew-right', 'stats-skew-left', 'stats-skew-symmetric');
  if v_n <> 3 then
    raise exception 'expected 3 figures, found %', v_n;
  end if;
end $$;

commit;
